<script setup lang="ts">
import {ref,computed,nextTick} from 'vue'
const initial=[{id:'report',title:'Sample report ready',body:'The fictitious monthly report is available.',read:false},{id:'review',title:'Sample review requested',body:'A fictitious project needs a review.',read:false},{id:'welcome',title:'Sample workspace welcome',body:'This is a read example from the local inbox.',read:true}]
const filterControl=ref<HTMLSelectElement>()
const items=ref(initial.map(x=>({...x}))),filter=ref('all'),selected=ref(''),feedback=ref('')
const unread=computed(()=>items.value.filter(x=>!x.read).length),visible=computed(()=>items.value.filter(x=>filter.value==='all'||!x.read)),detail=computed(()=>items.value.find(x=>x.id===selected.value))
function toggle(id:string){const item=items.value.find(x=>x.id===id);if(item){item.read=!item.read;if(filter.value==='unread'&&item.read)nextTick(()=>filterControl.value?.focus());feedback.value=`${item.title} marked ${item.read?'read':'unread'}.`}}
function open(id:string){selected.value=id;const item=items.value.find(x=>x.id===id);if(item)item.read=true;if(filter.value==='unread')nextTick(()=>filterControl.value?.focus());feedback.value='Sample detail opened locally and marked read.'}
function close(){selected.value='';nextTick(()=>filterControl.value?.focus())}
function markAll(){nextTick(()=>filterControl.value?.focus());items.value.forEach(x=>x.read=true);feedback.value='All sample notifications marked read.'}
function reset(){items.value=initial.map(x=>({...x}));filter.value='all';selected.value='';feedback.value='Sample inbox reset.'}
</script>
<template><section class="notification-usage" aria-label="Notification inbox demonstration"><p>Fictitious local inbox. Read state lasts only while this page is mounted. No email, push or server changes.</p><div class="options"><label>Inbox filter<select ref="filterControl" v-model="filter"><option value="all">All</option><option value="unread">Unread only</option></select></label><button type="button" :disabled="!unread" @click="markAll">Mark all read</button><button type="button" @click="reset">Reset sample inbox</button></div><p>{{unread}} unread · {{items.length}} total</p><ul class="inbox"><li v-for="item in visible" :key="item.id" :class="{unread:!item.read}"><div><strong>{{item.title}}</strong><span class="state">{{item.read?'Read':'Unread'}}</span><p>{{item.body}}</p></div><div class="actions"><button type="button" :aria-label="`Open ${item.title}`" @click="open(item.id)">Open detail</button><button type="button" :aria-label="`Mark ${item.title} ${item.read?'unread':'read'}`" @click="toggle(item.id)">Mark {{item.read?'unread':'read'}}</button></div></li></ul><p v-if="!visible.length" class="empty">No unread sample notifications. Choose All or reset the sample inbox.</p><section v-if="detail" class="detail" aria-label="Selected sample notification"><h3>{{detail.title}}</h3><p>{{detail.body}} This detail stays visible even when the item leaves the unread filter.</p><button type="button" @click="close">Close sample detail</button></section><p role="status">{{feedback}}</p></section></template>
<style scoped>
.notification-usage{padding:20px;margin:20px 0;border:1px solid var(--vp-c-divider);border-radius:12px}.options,.actions{display:flex;flex-wrap:wrap;gap:12px;align-items:end}label{display:flex;flex-direction:column;gap:8px}button,select{min-height:44px;padding:8px 12px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}button:disabled{opacity:.55}.inbox{list-style:none;padding:0;margin:16px 0}.inbox li{margin:12px 0;padding:16px;border:1px solid var(--vp-c-divider);border-left:4px solid transparent;border-radius:8px;animation:note-enter 160ms ease-out;transition:background 140ms ease-out}.inbox li.unread{border-left-color:var(--vp-c-brand-1);background:var(--vp-c-brand-soft)}.state{display:block;font-size:13px}.detail,.empty{padding:16px;border:1px solid var(--vp-c-divider);border-radius:8px}.detail h3{margin:0}.detail{animation:note-enter 160ms ease-out}:focus-visible{outline:3px solid var(--vp-c-brand-1);outline-offset:2px}@keyframes note-enter{from{opacity:.4;translate:0 3px}to{opacity:1;translate:0 0}}@media(prefers-reduced-motion:reduce){.inbox li,.detail{animation:none;transition:none}}
</style>
